#[tauri::command]
fn greet(name: &str) -> String {
    format!("Hello, {}! You've been greeted from Rust!", name)
}

#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
    tauri::Builder::default()
        .plugin(tauri_plugin_opener::init())
        .invoke_handler(tauri::generate_handler![greet])
        .setup(|app| {
            // 默认窗口 1600x1080。如果宽或高超出主显示器物理尺寸,直接最大化,
            // 避免窗口被任务栏/标题栏挤掉操作区,或在低分辨率屏上溢到屏幕外。
            const DEFAULT_W: f64 = 1600.0;
            const DEFAULT_H: f64 = 1080.0;
            if let Some(window) = app.get_webview_window("main") {
                if let Ok(Some(monitor)) = window.primary_monitor() {
                    let scale = monitor.scale_factor();
                    let mon_size = monitor.size(); // 物理像素
                    let req_w = (DEFAULT_W * scale).ceil() as u32;
                    let req_h = (DEFAULT_H * scale).ceil() as u32;
                    if req_w >= mon_size.width || req_h >= mon_size.height {
                        let _ = window.maximize();
                    }
                }
            }
            Ok(())
        })
        .run(tauri::generate_context!())
        .expect("error while running tauri application");
}

