use leptos::prelude::*;

#[component]
fn Sidebar(
    current: ReadSignal<&'static str>,
    set_current: WriteSignal<&'static str>,
) -> impl IntoView {
    // 侧边栏菜单项：(路由 key, 显示名称)
    let items: [(&'static str, &'static str); 2] = [
        ("stock", "股票查询"),
        ("datasources", "数据源管理"),
    ];

    view! {
        <aside class="sidebar">
            <div class="sidebar-header">"Menu"</div>
            <nav class="sidebar-nav">
                {items.into_iter().map(|(key, label)| {
                    let set_current = set_current;
                    view! {
                        <button
                            class=move || if current.get() == key { "nav-item active" } else { "nav-item" }
                            on:click=move |_| set_current.set(key)
                        >
                            {label}
                        </button>
                    }
                }).collect_view()}
            </nav>
        </aside>
    }
}

