#[component]
fn StockQueryPage() -> impl IntoView {
    // 用一个 tick 信号触发"刷新"假数据
    let (tick, set_tick) = signal(0u32);

    // 原始数据，每次 tick 触发一次响应式重算
    let stocks = move || {
        let _ = tick.get(); // 订阅 tick
        let mut s = fake_stocks();
        // 给价格加点基于 tick 的确定性抖动，让"刷新"看起来有点变化
        let bump = ((tick.get() as f64 * 0.37).sin()) * 0.6;
        for st in s.iter_mut() {
            st.price = (st.price + bump).max(0.01);
        }
        s
    };

    // 搜索过滤：按代码或名称包含子串（不区分大小写）
    let (query, set_query) = signal(String::new());

    let filtered = move || {
        let q = query.get().trim().to_lowercase();
        stocks()
            .into_iter()
            .filter(|s| {
                q.is_empty()
                    || s.code.to_lowercase().contains(&q)
                    || s.name.to_lowercase().contains(&q)
            })
            .collect::<Vec<_>>()
    };

    view! {
        <main class="page">
            <h1 class="page-title">"股票查询"</h1>

            <div class="toolbar">
                <input
                    class="search-input"
                    placeholder="输入股票代码或名称搜索..."
                    on:input=move |ev| set_query.set(event_target_value(&ev))
                    prop:value=query
                />
                <button class="primary-btn" on:click=move |_| set_tick.update(|n| *n += 1)>
                    "刷新"
                </button>
            </div>

            <div class="table-wrap">
                <table class="stock-table">
                    <thead>
                        <tr>
                            <th>"代码"</th>
                            <th>"名称"</th>
                            <th class="num">"现价(元)"</th>
                            <th class="num">"涨跌幅"</th>
                            <th class="num">"成交量(手)"</th>
                        </tr>
                    </thead>
                    <tbody>

